### File 2: src/components/document/Document.vue

```vue src/components/document/Document.vue
<script setup>
import SectionBlock from './SectionBlock.vue'
import parser from '@/utils/markdownParser'
</script>

<template>
  <div class="flex flex-col @container/document">
    <SectionBlock
      v-for="section in sections"
      :key="section.hash"
      :section="section"
      :files="files"
      :documentId="documentId"
      :docProject="docProject"
      :chat="chat"
      :message="message"
      :loading="loading"
      @add-file="$emit('add-file', $event)"
      @copy-section="handleCopySection"
      @create-task="handleCreateTask"
      @generate-code="$emit('generate-code', $event)"
      @reload-file="$emit('reload-file', { file: $event, message })"
      @open-file="$emit('open-file', $event)"
      @save-file="$emit('save-file', $event)"
      @edit-message="$emit('edit-message', $event)"
      @sub-task="$emit('sub-task', $event)"
    >
      <template #section-actions="{ section, fullContent }">
        <slot 
          name="section-actions" 
          :section="section"
          :full-content="fullContent"
        />
      </template>
    </SectionBlock>
  </div>
</template>

<script>
export default {
  props: {
    content: { type: String, default: '' },
    files: { type: Array, default: null },
    project: { type: Object, default: null },
    chat: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    documentId: { type: String, default: '' },
    message: { type: Object, default: null }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'sub-task',
    'copy-section',
    'create-task'
  ],
  data() {
    return {
      cachedSections: [],
      lastContentHash: null
    }
  },
  computed: {
    sections() {
      // During streaming, reparse to get new content updates
      // but sections with stable hashes won't unmount/remount
      const contentHash = this.loading
        ? this.content
        : this.getContentStructureHash()

      if (this.lastContentHash != null && contentHash === this.lastContentHash) {
        return this.cachedSections
      }

      this.lastContentHash = contentHash
      this.cachedSections = parser.parseSections(this.content || '')

      if (!this.loading) {
        parser.markAllFinished(this.cachedSections)
      } else if (this.cachedSections.length > 0) {
        parser.markLastUnfinished(this.cachedSections)
      }

      return this.cachedSections
    },
    docProject() {
      return this.project || this.$project
    }
  },
  methods: {
    getContentStructureHash() {
      const lines = (this.content || '').split('\n')
      let hash = ''
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]
        if (/^#{1,6}\s+/.test(line) || /^( {0,3})(`{3,}|~{3,})/.test(line)) {
          hash += i + ':' + line + '|'
        }
      }
      return hash
    },
    handleCopySection(sectionData) {
      this.$emit('copy-section', sectionData)
    },
    handleCreateTask(taskData) {
      this.$emit('create-task', taskData)
    }
  }
}
</script>
