### File 3: src/components/document/SectionBlock.vue

```vue src/components/document/SectionBlock.vue
<script setup>
import MarkdownViewer from '../MarkdownViewer.vue'
import Code from '../Code.vue'
import SectionBlock from './SectionBlock.vue'
import parser from '@/utils/markdownParser'
</script>

<template>
  <div 
    class="section-block transition-all duration-200 mb-4"
    @mouseenter="isHovered = true"
    @mouseleave="isHovered = false"
  >
    <!-- Section header with actions (only if section has heading) -->
    <div v-if="section.heading">
      <div class="flex items-center justify-between group/header">
        <div :class="'heading-' + section.level">
          <h1 v-if="section.level === 1" class="text-3xl font-bold">{{ section.title }}</h1>
          <h2 v-else-if="section.level === 2" class="text-2xl font-bold">{{ section.title }}</h2>
          <h3 v-else-if="section.level === 3" class="text-xl font-bold">{{ section.title }}</h3>
          <h4 v-else-if="section.level === 4" class="text-lg font-bold">{{ section.title }}</h4>
          <h5 v-else-if="section.level === 5" class="font-bold">{{ section.title }}</h5>
          <h6 v-else class="font-bold text-sm">{{ section.title }}</h6>
        </div>
        <div class="hidden group-hover/header:flex gap-2 items-center">
          <slot 
            name="section-actions" 
            :section="section"
            :full-content="section.fullContent"
          >
            <button
              class="btn btn-sm btn-ghost gap-2"
              @click="copySectionContent"
              :title="'Copy section: ' + (section.title || 'content')"
            >
              <i class="fa-solid fa-copy"></i>
              Copy
            </button>
            <button
              class="btn btn-sm btn-ghost gap-2"
              @click="createTaskFromSection"
              :title="'Create task from: ' + (section.title || 'content')"
            >
              <i class="fa-solid fa-tasks"></i>
              Task
            </button>
          </slot>
        </div>
      </div>
    </div>

    <!-- Section content (markdown and code blocks) -->
    <div class="space-y-4">
      <div v-for="block in sectionBlocks" :key="block.hash">
        <!-- Code block: has fileName or synthetic fileName -->
        <Code
          v-if="isCodeBlock(block)"
          :text="block.content"
          :text-language="block.type"
          :fileName="block.fileName"
          :files="files"
          :project="docProject"
          :finished="block.finished"
          :loading="loading"
          :chat="chat"
          :message="message"
          :block-hash="block.hash"
          @generate-code="$emit('generate-code', $event)"
          @reload-file="$emit('reload-file', $event)"
          @open-file="$emit('open-file', $event)"
          @save-file="$emit('save-file', $event)"
          @add-file="$emit('add-file', $event)"
          @edit-message="$emit('edit-message', $event)"
          @sub-task="$emit('sub-task', $event)"
        />
        <!-- Markdown block: no fileName and markdown/md type -->
        <MarkdownViewer
          v-else
          :files="files"
          :documentId="documentId"
          :text="block.content"
          @add-file="$emit('add-file', $event)"
          @copy-section="$emit('copy-section', $event)"
          @create-task="$emit('create-task', $event)"
        />        
      </div>
    </div>

    <!-- Render child sections -->
    <div v-if="section.children && section.children.length">
      <SectionBlock
        v-for="childSection in section.children"
        :key="childSection.hash"
        :section="childSection"
        :files="files"
        :documentId="documentId"
        :docProject="docProject"
        :loading="loading"
        :chat="chat"
        :message="message"
        @add-file="$emit('add-file', $event)"
        @copy-section="handleChildCopy"
        @create-task="$emit('create-task', $event)"
        @generate-code="$emit('generate-code', $event)"
        @reload-file="$emit('reload-file', $event)"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
      >
        <template #section-actions="{ section: childSection, fullContent }">
          <slot 
            name="section-actions" 
            :section="childSection"
            :full-content="fullContent"
          />
        </template>
      </SectionBlock>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    section: { type: Object, required: true },
    files: { type: Array, default: null },
    documentId: { type: String, default: '' },
    docProject: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    chat: { type: Object, default: null },
    message: { type: Object, default: null }
  },
  emits: [
    'add-file',
    'copy-section',
    'create-task',
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'edit-message',
    'sub-task'
  ],
  data() {
    return {
      isHovered: false
    }
  },
  computed: {
    sectionBlocks() {
      // Parse blocks from section content (excluding the heading line)
      const contentWithoutHeader = this.section.heading 
        ? parser.stripHeaderFromContent(this.section.content)
        : this.section.content
      return parser.parseBlocks(contentWithoutHeader || '')
    }
  },
  methods: {
    isCodeBlock(block) {
      return !!block.fileName
    },
    copySectionContent() {
      // Use fullContent which includes all descendant sections
      const content = this.section.fullContent
      navigator.clipboard.writeText(content).then(() => {
        this.$emit('copy-section', {
          title: this.section.title || 'Content',
          content: content,
          level: this.section.level
        })
      }).catch(err => {
        console.error('Failed to copy section content', err)
      })
    },
    createTaskFromSection() {
      const content = this.section.fullContent
      this.$emit('create-task', {
        title: this.section.title || 'New Task',
        description: content,
        level: this.section.level
      })
    },
    handleChildCopy(sectionData) {
      this.$emit('copy-section', sectionData)
    }
  }
}
</script>
