/**
 * Hash generator for stable block keys
 */
function generateHash(str) {
  let hash = 0
  for (const char of str) {
    hash = (hash << 5) - hash + char.charCodeAt(0)
    hash |= 0
  }
  return hash
}

/**
 * Heading detection helpers
 */
function isHeading(line) {
  return /^#{1,6}\s+/.test(line)
}

function getHeadingLevel(line) {
  const match = line.match(/^(#+)\s+/)
  return match ? match[1].length : 0
}

function getHeadingText(line) {
  return line.replace(/^#+\s+/, '').trim()
}

function isMarkdownBlockType(blockType) {
  return ['markdown', 'md', 'text'].includes(blockType)
}

/**
 * Get common file extension for language
 */
function getExtensionForLanguage(language) {
  const extensions = {
    'js': 'js',
    'javascript': 'js',
    'ts': 'ts',
    'typescript': 'ts',
    'python': 'py',
    'py': 'py',
    'java': 'java',
    'c': 'c',
    'cpp': 'cpp',
    'csharp': 'cs',
    'cs': 'cs',
    'php': 'php',
    'ruby': 'rb',
    'rb': 'rb',
    'go': 'go',
    'rust': 'rs',
    'rs': 'rs',
    'html': 'html',
    'css': 'css',
    'scss': 'scss',
    'json': 'json',
    'yaml': 'yaml',
    'yml': 'yml',
    'xml': 'xml',
    'sql': 'sql',
    'bash': 'sh',
    'sh': 'sh',
    'shell': 'sh',
    'vue': 'vue',
    'react': 'jsx',
    'jsx': 'jsx',
    'tsx': 'tsx'
  }
  return extensions[language.toLowerCase()] || language.toLowerCase()
}

/**
 * Generate synthetic filename from language type
 */
function generateFileName(language) {
  if (!language || language === 'text') return 'content.txt'
  const ext = getExtensionForLanguage(language)
  return `content.${ext}`
}

/**
 * Detect fence markers (``` or ~~~) with optional info string
 */
function getFence(line) {
  const match = line.match(/^( {0,3})(`{3,}|~{3,})(.*)$/)
  if (!match) return null
  return {
    char: match[2][0],
    length: match[2].length,
    info: match[3].trim()
  }
}

/**
 * Check if a line is a valid closing fence
 */
function isClosingFence(line, fence) {
  const lineFence = getFence(line)
  return !!(
    lineFence &&
    fence &&
    lineFence.char === fence.char &&
    lineFence.length >= fence.length &&
    !lineFence.info
  )
}

/**
 * Count matching closing fences ahead from index
 */
function countClosingFencesAhead(lines, fromIndex, fence) {
  let count = 0
  for (let i = fromIndex + 1; i < lines.length; i++) {
    if (isClosingFence(lines[i], fence)) count++
  }
  return count
}

/**
 * Decide if an anonymous fence should open a nested block or close the outer one
 */
function isNestedAnonymousFence(lines, index, currentType, currentFence) {
  const isMarkdownBlock = isMarkdownBlockType(currentType)
  return isMarkdownBlock && countClosingFencesAhead(lines, index, currentFence) >= 2
}

/**
 * Check if position is inside a code fence (any nesting level)
 */
function isInsideCodeFence(lines, lineIndex) {
  let currentFence = null
  let nestStack = []

  for (let i = 0; i < lineIndex; i++) {
    const fence = getFence(lines[i])
    if (!fence) continue

    if (!currentFence) {
      currentFence = fence
      nestStack = [fence]
      continue
    }

    const lastNested = nestStack[nestStack.length - 1]
    if (lastNested && isClosingFence(lines[i], lastNested)) {
      nestStack.pop()
      continue
    }

    if (!nestStack.length && isClosingFence(lines[i], currentFence)) {
      if (isNestedAnonymousFence(lines, i, 'unknown', currentFence)) {
        nestStack.push(fence)
        continue
      }
      currentFence = null
      nestStack = []
    }
  }

  return !!currentFence
}

/**
 * Parse content into typed blocks with fence handling
 */
function parseBlocks(content, getRendererFn = getRenderer) {
  const blocks = []
  const lines = content.split('\n')
  let currentType = 'markdown'
  let currentContent = []
  let currentFileName = ''
  let inCodeBlock = false
  let currentFence = null
  let nestedFences = []
  let isAnonymousFence = false

  function addBlock(isFinished = false) {
    const blockContent = currentContent.join('\n')
    const trimmedContent = blockContent.trim()

    if (!trimmedContent) {
      resetBlock()
      return
    }

    let finalFileName = currentFileName
    let finalType = currentType

    if (finalType && !isMarkdownBlockType(finalType) && !finalFileName && !isAnonymousFence) {
      finalFileName = generateFileName(finalType)
    }

    const contentHash = generateHash(blockContent)

    blocks.push({
      type: finalType,
      content: blockContent,
      hash: contentHash,
      fileName: finalFileName,
      renderer: getRendererFn(finalType, finalFileName),
      finished: isFinished
    })

    resetBlock()
  }

  function resetBlock() {
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
    currentFence = null
    nestedFences = []
    isAnonymousFence = false
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const fence = getFence(line)

    if (!inCodeBlock && fence) {
      const hasLanguageInfo = fence.info && fence.info.trim()

      if (hasLanguageInfo) {
        if (blocks.length > 0) {
          blocks[blocks.length - 1].finished = true
        }

        if (currentContent.length) addBlock(true)

        const parts = fence.info.split(/\s+/).filter(Boolean)
        inCodeBlock = true
        currentFence = fence
        currentType = parts[0] || 'text'
        currentFileName = parts[1] || ''
        isAnonymousFence = false
        continue
      } else {
        if (!inCodeBlock) {
          currentContent.push(line)
          continue
        }
      }
    }

    if (!inCodeBlock) {
      currentContent.push(line)
      continue
    }

    const topNested = nestedFences[nestedFences.length - 1]

    if (topNested && isClosingFence(line, topNested)) {
      nestedFences.pop()
      currentContent.push(line)
      continue
    }

    if (isMarkdownBlockType(currentType)) {
      const innerFence = getFence(line)
      if (innerFence && innerFence.info && !isClosingFence(line, currentFence)) {
        nestedFences.push(innerFence)
        currentContent.push(line)
        continue
      }
    }

    const allNestedClosed = !nestedFences.length
    if (allNestedClosed && isClosingFence(line, currentFence)) {
      if (isNestedAnonymousFence(lines, i, currentType, currentFence)) {
        nestedFences.push(currentFence)
        currentContent.push(line)
        continue
      }
      addBlock(true)
      inCodeBlock = false
      continue
    }

    currentContent.push(line)
  }

  if (currentContent.length) {
    addBlock(false)
  }

  for (let i = 0; i < blocks.length - 1; i++) {
    blocks[i].finished = true
  }

  return blocks
}

/**
 * Get renderer function
 */
function getRenderer(blockType, fileName) {
  if (fileName) return 'code'
  if (blockType === 'markdown' || blockType === 'md') return 'md'
  if (blockType === 'html') return blockType
  return 'code'
}

/**
 * NEW: Parse content into sections with parent-child hierarchy
 * Sections are defined by heading levels (h1, h2, h3, etc.)
 * Each section can start with a heading or plain content
 * When copying a section, all descendant sections are included
 */
function parseSections(content) {
  const lines = content.split('\n')
  const sections = []
  let i = 0

  // Parse intro section (content before first heading)
  const introLines = []
  while (i < lines.length && (!isHeading(lines[i]) || isInsideCodeFence(lines, i))) {
    introLines.push(lines[i])
    i++
  }

  const introContent = introLines.join('\n').trim()
  if (introContent) {
    sections.push({
      level: 0,
      heading: null,
      title: null,
      startIndex: 0,
      endIndex: i,
      content: introContent,
      children: [],
      hash: generateHash(introContent),
      finished: false
    })
  }

  // Parse heading-based sections
  while (i < lines.length) {
    const line = lines[i]

    if (isHeading(line) && !isInsideCodeFence(lines, i)) {
      const section = parseSection(lines, i)
      sections.push(section)
      i = section.endIndex
    } else {
      i++
    }
  }

  return sections
}

/**
 * Parse a single section from lines, including child sections
 */
function parseSection(lines, startIndex) {
  const headingLine = lines[startIndex]
  const level = getHeadingLevel(headingLine)
  const title = getHeadingText(headingLine)
  const sectionLines = [headingLine]
  const children = []
  let i = startIndex + 1

  // Collect all content until next heading of same or higher level
  while (i < lines.length) {
    const line = lines[i]

    if (isHeading(line) && !isInsideCodeFence(lines, i)) {
      const nextLevel = getHeadingLevel(line)

      // Same or higher level heading = end of this section
      if (nextLevel <= level) break

      // Child heading
      if (nextLevel === level + 1) {
        const childSection = parseSection(lines, i)
        children.push(childSection)
        i = childSection.endIndex
        continue
      }

      // Orphaned deeper heading (skip levels) - treat as content
      if (nextLevel > level + 1) {
        sectionLines.push(line)
        i++
        continue
      }
    }

    sectionLines.push(line)
    i++
  }

  // Generate full content including all descendants
  const fullContent = collectSectionContent(sectionLines, children)

  return {
    level,
    heading: headingLine,
    title,
    startIndex,
    endIndex: i,
    content: sectionLines.join('\n'),
    fullContent: fullContent,
    children,
    hash: generateHash(fullContent),
    finished: false
  }
}

/**
 * Collect full content of section including all children
 * This is used when copying a section with descendants
 */
function collectSectionContent(sectionLines, children) {
  let content = sectionLines.join('\n')

  if (children && children.length > 0) {
    for (const child of children) {
      content += '\n' + child.fullContent
    }
  }

  return content.trim()
}

/**
 * Recursively collect all sections flat (for iteration)
 */
function flattenSections(sections) {
  const flat = []

  for (const section of sections) {
    flat.push(section)
    if (section.children && section.children.length > 0) {
      flat.push(...flattenSections(section.children))
    }
  }

  return flat
}

/**
 * Strip first heading line from content
 */
function stripHeaderFromContent(content) {
  const lines = content.split('\n')
  if (lines.length > 0 && isHeading(lines[0])) {
    return lines.slice(1).join('\n').trim()
  }
  return content
}

/**
 * Mark all sections as finished recursively
 */
function markAllFinished(sections) {
  for (const section of sections) {
    section.finished = true
    if (section.children && section.children.length > 0) {
      markAllFinished(section.children)
    }
  }
}

/**
 * Mark last section as unfinished recursively
 */
function markLastUnfinished(sections) {
  if (!sections.length) return

  for (let i = sections.length - 1; i >= 0; i--) {
    const section = sections[i]
    if (section.children && section.children.length > 0) {
      markLastUnfinished(section.children)
      return
    }
    section.finished = false
    return
  }
}

export default {
  generateHash,
  isHeading,
  getHeadingLevel,
  getHeadingText,
  stripHeaderFromContent,
  getRenderer,
  getFence,
  isClosingFence,
  countClosingFencesAhead,
  isNestedAnonymousFence,
  isInsideCodeFence,
  parseBlocks,
  parseSections,
  parseSection,
  collectSectionContent,
  flattenSections,
  markAllFinished,
  markLastUnfinished,
  generateFileName,
  getExtensionForLanguage
}

